import{_ as e,o,c as i,a5 as t}from"./chunks/framework.CXvGqWf0.js";const b=JSON.parse('{"title":"漫画 · 第 68 话 可访问性审计","description":"","frontmatter":{},"headers":[],"relativePath":"comics/quality/EP.68-accessibility-audit.md","filePath":"comics/quality/EP.68-accessibility-audit.md","lastUpdated":1793853676000}'),c={name:"comics/quality/EP.68-accessibility-audit.md"};function d(l,a,r,s,n,h){return o(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="漫画-·-第-68-话-可访问性审计" tabindex="-1">漫画 · 第 68 话 可访问性审计 <a class="header-anchor" href="#漫画-·-第-68-话-可访问性审计" aria-label="Permalink to &quot;漫画 · 第 68 话 可访问性审计&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/quality/02-accessibility-audit">docs/quality/02-accessibility-audit.md</a> ｜ 原画：<a href="./EP.68-accessibility-audit.svg">EP.68-accessibility-audit.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师。她做的后台 Lighthouse 可访问性 92 分，却被客服投诉「键盘交不了表单」。</li><li><strong>码叔</strong>：老工程师。他不看分数，先让像素酱只用键盘走一遍完整任务。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>审计报告一片绿，但真实任务卡住：提交按钮是 <code>div</code> 加 <code>onclick</code>，Tab 根本聚焦不到；弹窗打开后焦点还留在背景；浅灰说明文字对比度不足。码叔把 <code>div</code> 换成原生 <code>button</code>，弹窗打开时移入焦点、用 <code>inert</code> 移出背景，并让审计脚本实测对比度与聚焦轮廓。键盘任务完成率从 60% 升到 100%。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>自动扫描擅长发现机械问题：缺 <code>alt</code>、缺 <code>label</code>、对比度不足。但它测不出「能不能用键盘完成任务」。分数高只说明机械问题少，不说明路径通。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三个用户路径对应三类审计：键盘用户依赖 Tab 顺序与焦点可见；读屏用户依赖角色、名称与状态；低视力用户依赖对比度与缩放。<code>button</code> 自带角色、焦点与回车触发；<code>div</code> 假按钮三样都缺。焦点可见用 <code>:focus-visible</code> 提供轮廓，弹层用 <code>inert</code> 把背景移出焦点顺序。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>码叔的审计脚本实时计算对比度、检查 <code>alt</code> 与 <code>label</code>、实测聚焦后的轮廓、校验标题层级，并识别「不可聚焦的 onclick 元素」。示例里切到修复版，六项检查全部变绿；问题版的说明文字对比度只有约 2:1，直接被标红。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>优先原生元素：<code>button</code>、<code>a</code>、<code>input</code>、<code>dialog</code> 自带语义与键盘行为。</li><li>图标按钮必须有可访问名称，装饰图用 <code>alt=&quot;&quot;</code>。</li><li>移除 <code>outline</code> 必须提供替代，焦点环在两套主题都要够对比。</li><li>弹层要管焦点：打开移入、关闭归还、背景 <code>inert</code>。</li><li>对比度按主题实测：正文 4.5:1、大字 3:1。</li><li>自动扫描只是起点，键盘与读屏走查不可省。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么把 <code>div</code> 改成 <code>button</code> 能同时解决读屏和键盘两个问题？</p><p><strong>答</strong>：原生 <code>button</code> 自带按钮角色，读屏会播报「按钮」及其名称；它默认进入 Tab 顺序，并响应 Enter / Space。<code>div</code> 加 <code>onclick</code> 只有鼠标能触发，既没有角色也没有焦点。用 <code>div</code> 重造按钮，等于把浏览器免费提供的三件事全部自己实现一遍，通常还会漏。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>切换问题版 / 修复版，观察六项审计结果变化：<a href="./../../examples/quality/02-accessibility-audit">examples/quality/02-accessibility-audit</a></li><li>只用 Tab / Shift+Tab / Enter，尝试在两个版本里完成「填表 → 提交」。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 69 话《性能预算与 CI 门禁》——预算写在文档里没有约束力，接进流水线才有。</p>',22)])])}const q=e(c,[["render",d]]);export{b as __pageData,q as default};
